warp:
shader_body
{
vec2 _uv = uv;

    // sample previous frame
    ret = texture( sampler_main, _uv ).xyz;
    ret += texture(sampler_blur2, _uv).xyz*0.1;
    ret /= 1.1;

    // darken over time
    ret -= 0.02;//*= 0.95; //or try: ret -= 0.004;

}

comp:
shader_body
{
    ret = texture(sampler_main, uv).xyz*1.0 +
              ((texture(sampler_blur1, uv).xyz * scale1) + bias1)*3.0 +
              ((texture(sampler_blur2, uv).xyz * scale2) + bias2)*0.0 +
              ((texture(sampler_blur3, uv).xyz * scale3) + bias3)*0.0.0 +
              0;
    ret += ((texture(sampler_blur2,  (uv-0.5)*0.333 + 0.5).xyz * scale2) + bias2);
    ret *= 1.0;

}
